const assert = require('assert');
const { deliver } = require('/workspace/src/dispatcher.js');

(async () => {
  // 1. Retries on 502 then succeeds
  let calls = 0;
  let seenHeaders;
  const io1 = {
    async post(path, event, opts) {
      calls++;
      seenHeaders = opts.headers;
      return calls === 1 ? { status: 502 } : { status: 200, body: 'ok' };
    },
  };
  const r1 = await deliver(io1, { id: 'evt-1', type: 'a' });
  assert.strictEqual(calls, 2, 'should retry once after 502');
  assert.strictEqual(r1.status, 200);
  assert.strictEqual(seenHeaders['X-Event-Id'], 'evt-1', 'must send X-Event-Id');
  console.log('1. retry-on-502 -> success: OK');

  // 2. Does not retry on 4xx
  calls = 0;
  const io2 = { async post() { calls++; return { status: 400 }; } };
  const r2 = await deliver(io2, { id: 'evt-2' });
  assert.strictEqual(calls, 1, '4xx must not be retried');
  assert.strictEqual(r2.status, 400);
  console.log('2. no-retry-on-4xx: OK');

  // 3. Retries on network error then succeeds
  calls = 0;
  const io3 = {
    async post(path, event, opts) {
      calls++;
      if (calls === 1) throw new Error('ECONNREFUSED');
      return { status: 201 };
    },
  };
  const r3 = await deliver(io3, { id: 'evt-3' });
  assert.strictEqual(calls, 2);
  assert.strictEqual(r3.status, 201);
  console.log('3. retry-on-network-error -> success: OK');

  // 4. Respects Retry-After header
  calls = 0;
  const io4 = {
    async post() {
      calls++;
      if (calls === 1) return { status: 503, headers: { 'retry-after': '0' } };
      return { status: 200 };
    },
  };
  const r4 = await deliver(io4, { id: 'evt-4' });
  assert.strictEqual(calls, 2);
  assert.strictEqual(r4.status, 200);
  console.log('4. retry-after header: OK');

  // 5. Gives up after maxAttempts and returns last response
  calls = 0;
  const io5 = { async post() { calls++; return { status: 502 }; } };
  const r5 = await deliver(io5, { id: 'evt-5' }, { maxAttempts: 3 });
  assert.strictEqual(calls, 3, 'should stop after maxAttempts');
  assert.strictEqual(r5.status, 502);
  console.log('5. exhaustion returns last response: OK');

  // 6. Throws after exhausting retries on network errors
  calls = 0;
  const io6 = { async post() { calls++; throw new Error('down'); } };
  await assert.rejects(deliver(io6, { id: 'evt-6' }, { maxAttempts: 2 }), /down/);
  assert.strictEqual(calls, 2);
  console.log('6. exhaustion on network error throws: OK');

  // 7. Backwards compatible: success path still returns response, fallback id
  const io7 = { async post(path, event) { return { statusCode: 200 }; } };
  const r7 = await deliver(io7, { eventId: 'e7' });
  assert.strictEqual(r7.statusCode, 200);
  console.log('7. statusCode + eventId fallback: OK');

  console.log('ALL SMOKE TESTS PASSED');
})().catch((e) => { console.error('FAILED:', e); process.exit(1); });
"

